import 'package:flutter/material.dart';

import '../theme/app_theme.dart';
import '../theme/tokens.g.dart';

/// The Gleefy mark: the grinning party face from the app icon (assets/brand/mark.png, generated by
/// scripts/brand-icons.mjs from the same drawing).
class GleefyMark extends StatelessWidget {
  const GleefyMark({super.key, this.size = 40});

  final double size;

  @override
  Widget build(BuildContext context) => ExcludeSemantics(
    child: Image.asset('assets/brand/mark.png', height: size, filterQuality: FilterQuality.medium),
  );
}

class GleefyWordmark extends StatelessWidget {
  const GleefyWordmark({super.key, this.size = 28});

  final double size;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      header: true,
      label: 'Gleefy',
      child: ExcludeSemantics(
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            GleefyMark(size: size * 1.2),
            const SizedBox(width: GfSpace.s2),
            Text(
              'Gleefy',
              style: TextStyle(fontFamily: GfFont.display, fontWeight: FontWeight.w700, fontSize: size),
            ),
          ],
        ),
      ),
    );
  }
}

/// A rounded card filled with the brand gradient. Text on it is white (contrast tested in tokens).
class GradientPanel extends StatelessWidget {
  const GradientPanel({super.key, required this.child, this.onTap, this.padding = const EdgeInsets.all(GfSpace.s6)});

  final Widget child;
  final VoidCallback? onTap;
  final EdgeInsets padding;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: BoxDecoration(
        gradient: GfPalette.of(context).gradient,
        borderRadius: BorderRadius.circular(GfRadius.xl),
      ),
      child: Material(
        type: MaterialType.transparency,
        child: InkWell(
          borderRadius: BorderRadius.circular(GfRadius.xl),
          onTap: onTap,
          child: Padding(
            padding: padding,
            child: DefaultTextStyle.merge(
              style: const TextStyle(color: Colors.white),
              child: IconTheme.merge(
                data: const IconThemeData(color: Colors.white),
                child: child,
              ),
            ),
          ),
        ),
      ),
    );
  }
}
